cat > $B/data-export/route.ts <<'EOF'
/**
 * GET /api/v3/account/data-export - the signed-in user's own account data (name, email, locale,
 * notification settings, organization memberships).
 *
 * Session-only, deliberately: an export of one person's data is for that person, so accepting
 * `x-api-key` here would widen the surface rather than serve a need.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { exportV3AccountData } from "../lib/operations";

export const GET = withV3ApiWrapper({
  auth: "session",
  handler: async ({ authentication, requestId, instance }) =>
    exportV3AccountData({ authentication, requestId, instance }),
});
EOF
cat > $B/lib/serializers.ts <<'EOF'
import type { TUserNotificationSettings } from "@formbricks/types/user";

export type TV3AccountDataExport = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: TUserNotificationSettings;
  organizationMemberships: { organizationName: string; role: string }[];
};

type TAccountDataSource = {
  name: string;
  email: string;
  locale: string;
  notificationSettings: TUserNotificationSettings;
  memberships: { role: string; organization: { name: string } }[];
};

export const serializeV3AccountDataExport = (user: TAccountDataSource): TV3AccountDataExport => ({
  name: user.name,
  email: user.email,
  locale: user.locale,
  notificationSettings: user.notificationSettings,
  organizationMemberships: user.memberships.map((membership) => ({
    organizationName: membership.organization.name,
    role: membership.role,
  })),
});
EOF
cat > $B/lib/operations.ts <<'EOF'
import "server-only";
import { prisma } from "@formbricks/database";
import { getV3SessionUserId } from "@/app/api/v3/lib/auth";
import { problemUnauthorized, successResponse } from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import { serializeV3AccountDataExport } from "./serializers";

type TBaseParams = {
  authentication: TV3Authentication;
  requestId: string;
  instance?: string;
};

/**
 * Only the signed-in user's own row is read, keyed by the session's user id, so there is no caller-supplied
 * id to forge. Pending invitations (`accepted: false`) are not memberships yet and stay out. Ordered so the
 * file is stable between downloads.
 */
export async function exportV3AccountData({
  authentication,
  requestId,
  instance,
}: TBaseParams): Promise<Response> {
  const userId = getV3SessionUserId(authentication);
  if (!userId) return problemUnauthorized(requestId, undefined, instance);

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      name: true,
      email: true,
      locale: true,
      notificationSettings: true,
      memberships: {
        where: { accepted: true },
        orderBy: { organization: { name: "asc" } },
        select: { role: true, organization: { select: { name: true } } },
      },
    },
  });
  if (!user) return problemUnauthorized(requestId, undefined, instance);

  return successResponse(serializeV3AccountDataExport(user), { requestId });
}
EOF
cat > $B/lib/operations.test.ts <<'EOF'
import { beforeEach, describe, expect, test, vi } from "vitest";
import { prisma } from "@formbricks/database";
import { exportV3AccountData } from "./operations";

vi.mock("server-only", () => ({}));
vi.mock("@formbricks/database", () => ({ prisma: { user: { findUnique: vi.fn() } } }));

const base = { requestId: "req_1", instance: "/api/v3/account/data-export" };

describe("exportV3AccountData", () => {
  beforeEach(() => vi.clearAllMocks());

  test("answers 401 without a session user", async () => {
    const response = await exportV3AccountData({ ...base, authentication: null });
    expect(response.status).toBe(401);
    expect(prisma.user.findUnique).not.toHaveBeenCalled();
  });

  test("returns only the signed-in user's own data, memberships as organization name and role", async () => {
    vi.mocked(prisma.user.findUnique).mockResolvedValue({
      name: "Ada",
      email: "ada@example.com",
      locale: "en-US",
      notificationSettings: { alert: { weeklySummary: true } },
      memberships: [{ role: "owner", organization: { name: "Acme" } }],
    } as never);

    const response = await exportV3AccountData({
      ...base,
      authentication: { user: { id: "user_1" }, expires: "" },
    });

    expect(prisma.user.findUnique).toHaveBeenCalledWith(
      expect.objectContaining({ where: { id: "user_1" } })
    );
    expect(await response.json()).toEqual({
      data: {
        name: "Ada",
        email: "ada@example.com",
        locale: "en-US",
        notificationSettings: { alert: { weeklySummary: true } },
        organizationMemberships: [{ organizationName: "Acme", role: "owner" }],
      },
    });
  });
});
EOF
